'use strict';
(()=>{
const C=window.PLANOS,KEY='ludaria_planos_arquitecto_v1',$=id=>document.getElementById(id),N=C.pages.length;
const fresh=()=>({version:1,page:0,visited:[0],fields:{},choices:[null,null],seals:['pending','pending'],hints:[false,false],opened:[],tab:0,interest:null,timer:360});
let state=fresh(),storageOK=true,feedback={},running=false,opener=null,toastTimeout;
try{const s=JSON.parse(localStorage.getItem(KEY)||'null');if(s?.version===1){state.page=Number.isInteger(s.page)&&s.page>=0&&s.page<N?s.page:0;state.visited=Array.isArray(s.visited)?[...new Set(s.visited.filter(n=>Number.isInteger(n)&&n>=0&&n<N))]:[0];for(const k of Object.keys(C.fields))if(typeof s.fields?.[k]==='string')state.fields[k]=s.fields[k].slice(0,6000);for(let i=0;i<2;i++){state.choices[i]=[0,1,2].includes(s.choices?.[i])?s.choices[i]:null;state.seals[i]=s.seals?.[i]==='assisted'?'assisted':s.seals?.[i]==='solved'&&state.choices[i]===C.quizzes[i].correct?'solved':'pending';state.hints[i]=s.hints?.[i]===true;}state.opened=Array.isArray(s.opened)?s.opened.filter(x=>C.dimensions.some(d=>d.id===x)):[];state.tab=[0,1,2].includes(s.tab)?s.tab:0;state.interest=[0,1].includes(s.interest)?s.interest:null;state.timer=Number.isInteger(s.timer)?Math.max(0,Math.min(360,s.timer)):360;}}catch(e){storageOK=false;}
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch(e){storageOK=false;}}
const b=(action,text,attrs='',secondary=false)=>`<button class="button ${secondary?'secondary':''}" data-action="${action}" ${attrs}>${text}</button>`;
const t=(action,text,attrs='')=>`<button class="text-button" data-action="${action}" ${attrs}>${text}</button>`;
const field=(id,scope='page')=>`<label class="field" for="field-${scope}-${id}">${C.fields[id].label}<textarea id="field-${scope}-${id}" data-field="${id}" maxlength="6000" rows="3" placeholder="${esc(C.fields[id].placeholder)}">${esc(state.fields[id])}</textarea></label>`;
const status=x=>x==='solved'?'Resuelto':x==='assisted'?'Apertura acompañada':'Por resolver';
const clock=()=>`${String(Math.floor(state.timer/60)).padStart(2,'0')}:${String(state.timer%60).padStart(2,'0')}`;
const title=n=>`<div class="section-title"><div><span class="eyebrow">LA FORJA · FORJADOR ONDAL · CREACIÓN</span><h2>${C.pages[n].title}</h2></div><span class="time-label">${C.pages[n].time} min · ${n===12?'entre pares':'en clase'}</span></div><p class="lead">${C.pages[n].prompt}</p>`;
const scene=(n,body)=>`<section class="scene"><div class="scene-content wide">${title(n)}${body}<p class="note product">Producto: ${C.pages[n].product}</p></div></section>`;
const source=()=>`<p class="source-note">Marco 6D: Werbach y Hunter (2012). Adaptación educativa y caso: elaboración propia. ${t('sources','Fuentes y alcance')}</p>`;
const tiles=(example=false)=>`<div class="canvas-grid ${example?'example':''}">${C.dimensions.map(d=>`<button class="canvas-tile" data-action="dimension" data-dim="${d.id}"><span class="eyebrow">${d.tag}${state.opened.includes(d.id)?' · CONSULTADA':''}</span><h3>${d.title}</h3><p>${example?d.model:d.question}</p></button>`).join('')}</div>`;
function quiz(i){const q=C.quizzes[i];return `<div class="split challenge-split"><div><h3 class="question-title">${q.question}</h3><div class="options">${q.options.map((o,n)=>`<button class="choice ${state.choices[i]===n?'selected':''}" data-action="choice" data-quiz="${i}" data-option="${n}" aria-pressed="${state.choices[i]===n}"><span class="choice-mark">${String.fromCharCode(65+n)}</span><span>${o.text}</span></button>`).join('')}</div><div class="actions">${b('check','Revisar mi decisión',`data-quiz="${i}"`)}${t('hint','Pedir una pista',`data-quiz="${i}"`)}</div>${feedback[i]?`<div class="feedback ${feedback[i].kind}" role="status" tabindex="-1">${feedback[i].text}</div>`:''}${state.hints[i]?`<p class="note">Pista: ${q.hint}</p>`:''}<p class="note">${t('assist','Abrir con acompañamiento',`data-quiz="${i}"`)} · Puedes seguir sin resolver.</p></div><aside class="lock-panel ${state.seals[i]!=='pending'?'open':''}"><div class="lock-glyph" aria-hidden="true"><svg viewBox="0 0 48 48"><rect x="10" y="21" width="28" height="22" rx="3"/><path d="M16 21v-7a8 8 0 0 1 16 0v7"/><circle cx="24" cy="31" r="2"/></svg></div><span class="eyebrow">CANDADO ${i+1}</span><h3>${q.name}</h3><p>${status(state.seals[i])}</p>${state.seals[i]!=='pending'?b('reward','Consultar la pauta',`data-quiz="${i}"`,true):'<p class="note">Pauta complementaria. Contenido y canvas siguen disponibles.</p>'}</aside></div>`;}
const groups=[['goal','behavior'],['players','loops'],['fun','tools']];
function page(n){switch(n){
case 0:return `<section class="scene"><div class="cover-content"><span class="eyebrow">MISIÓN PRINCIPAL · MÓDULO 3 · SESIÓN 8</span><h1 class="cover-title">Los Planos<br>del <span>Arquitecto</span></h1><p class="lead">Una experiencia comienza con una intención.<br>Convirtamos el aprendizaje en decisiones de diseño.</p><div class="cover-meta"><span class="small-line"></span><span>Forja del Arquitecto · Forjador Ondal</span></div><div class="actions">${b('begin','Entrar a la Forja')}${b('guide','Guía docente','',true)}</div><p class="note">90 minutos sincrónicos · 60 asincrónicos · Creación</p></div></section>`;
case 1:return scene(n,`<blockquote class="mentor">“Antes del primer golpe, hagan visible qué quieren construir.”<small>ONDAL · VOZ NARRATIVA DE ESTA CLASE</small></blockquote><div class="three-column"><article class="panel"><span class="num">01</span><h3>Conocer el plano</h3><p>Seis decisiones para relacionar aprendizaje, participación y experiencia.</p></article><article class="panel"><span class="num">02</span><h3>Ver un modelo</h3><p>Un caso ficticio resuelto, para conversar las relaciones del diseño.</p></article><article class="panel"><span class="num">03</span><h3>Iniciar tu proyecto</h3><p>Objetivo y conductas esperadas, con una primera revisión entre pares.</p></article></div><p class="note">El facilitador conduce la clase. Cada dispositivo conserva su borrador; no hay sincronización del grupo.</p>`);
case 2:return scene(n,tiles()+`<div class="actions">${t('model','Ver el ejemplo completo')}${t('notebook','Abrir mi canvas')}</div><p class="note">Un proceso iterativo: pueden volver a una decisión cuando otra cambia. Esta plantilla educativa es propia; las seis preguntas mantienen el marco de los autores.</p>`+source());
case 3:return scene(n,`<p class="note">D1: describe el aprendizaje que buscamos. El premio y el número de visitas no lo sustituyen.</p>${quiz(0)}${source()}`);
case 4:return scene(n,`<p class="note">D2: concreta una acción y la huella que permitirá revisarla. La evidencia requiere interpretación humana.</p>${quiz(1)}${source()}`);
case 5:return scene(n,`<div class="three-column"><article class="panel"><span class="num">CONTEXTO</span><h3>Curso y condiciones</h3><p>En el caso ficticio, 7.º básico trabaja explicaciones científicas. La propuesta puede desarrollarse con tarjetas y hojas.</p></article><article class="panel"><span class="num">ESCUCHA</span><h3>Información pendiente</h3><p>Preguntar por formas de participar, conocimientos previos y apoyos. No asignar preferencias a todo el grupo.</p></article><article class="panel"><span class="num">DISEÑO</span><h3>Opciones equivalentes</h3><p>Explicar con esquema, texto o conversación, manteniendo el propósito y la justificación con evidencia.</p></article></div><div class="actions">${b('dimension','Consultar D3 del modelo','data-dim="players"',true)}${t('edit','Anotar qué necesito conocer','data-field-id="players"')}</div>${source()}`);
case 6:return scene(n,`<div class="loop-flow">${[['1','Explorar','Seleccionar una tarjeta de evidencia.'],['2','Proponer','Explicar qué modelo representa el fenómeno.'],['3','Recibir','Escuchar una pregunta sobre la evidencia.'],['4','Revisar','Precisar la explicación y volver a contrastar.']].map(([num,h,p],i)=>`<button class="loop-step" data-action="loop" data-option="${i}"><span class="num">${num}</span><h3>${h}</h3><p>${p}</p></button>`).join('')}</div><div class="progression" aria-label="Progresión del ejemplo"><span>1 · Reconocer procesos</span><span>2 · Contrastar modelos</span><span>3 · Argumentar una decisión</span></div><p class="note">Bucle: revisión de un intento. Progresión: desafíos que se conectan. Secuencia propia del caso; se puede volver a revisar.</p>${source()}`);
case 7:return scene(n,`<div class="split"><article class="panel"><span class="eyebrow">D5 · HIPÓTESIS DE DISEÑO</span><h3>Un misterio científico</h3><p>El grupo recibe explicaciones que no coinciden. Puede elegir por qué evidencia empezar y defender una interpretación.</p><p class="note">Se necesita preguntar cómo vivieron la actividad y observar qué favorece el aprendizaje.</p></article><div><h3>¿Qué probarías primero?</h3><div class="actions">${['Elegir por dónde explorar','Comparar ideas con un par'].map((x,i)=>b('interest',x,`data-option="${i}" aria-pressed="${state.interest===i}"`,true)).join('')}</div><p class="note">Elección personal para conversar. Ambas posibilidades requieren contraste; no hay puntuación.</p>${t('edit','Registrar una hipótesis para mi proyecto','data-field-id="fun"')}</div></div>${source()}`);
case 8:return scene(n,`<div class="three-column"><article class="panel"><span class="num">LOCAL</span><h3>Tarjetas y hoja</h3><p>Comparar evidencias, escribir la explicación y conservar una revisión. El facilitador acompaña con preguntas.</p></article><article class="panel"><span class="num">DIGITAL</span><h3>Documento equivalente</h3><p>Compartir explicaciones por el canal real de clase. Elegir una herramienta que permita leer y revisar el trabajo.</p></article><article class="panel"><span class="num">FUNCIÓN</span><h3>Una regla visible</h3><p>Las etapas muestran qué revisar. No representan un ranking ni una acreditación automática.</p></article></div><div class="actions">${b('dimension','Consultar D6 del modelo','data-dim="tools"',true)}${t('edit','Justificar un recurso de mi proyecto','data-field-id="tools"')}</div>${source()}`);
case 9:return scene(n,`<table class="framework-table"><caption class="skip">Perspectivas complementarias para diseñar</caption><thead><tr><th>Marco</th><th>Qué miramos</th><th>Ampliar</th></tr></thead><tbody><tr><th>6D</th><td>Decisiones del proceso de diseño.</td><td>${t('framework','Seis decisiones','data-option="0"')}</td></tr><tr><th>Octalysis</th><td>Ocho impulsores propuestos para analizar motivación.</td><td>${t('framework','Ocho impulsores','data-option="1"')}</td></tr><tr><th>Toda et al.</th><td>Vocabulario de elementos para contextos educativos.</td><td>${t('framework','Taxonomía','data-option="2"')}</td></tr></tbody></table><p class="note">Sus categorías responden a preguntas diferentes. Ninguno garantiza resultados por incorporar elementos.</p><div class="actions">${t('sources','Referencias y límites de cada marco')}</div>`);
case 10:return scene(n,`<p class="note model-caption">CASO FICTICIO · Ciencias Naturales, 7.º básico · Explicar el ciclo del agua. Selecciona una decisión para ver su detalle.</p>${tiles(true)}<div class="actions">${t('model','Leer el modelo completo en una ventana')}</div>`);
case 11:return scene(n,`<div class="worksheet-tabs" role="tablist" aria-label="Decisiones de mi canvas">${['Objetivo y acciones','Participantes y bucles','Experiencia y recursos'].map((x,i)=>`<button role="tab" id="tab-${i}" aria-controls="worksheet-panel" aria-selected="${state.tab===i}" tabindex="${state.tab===i?0:-1}" data-action="tab" data-option="${i}">${x}</button>`).join('')}</div><div class="worksheet" id="worksheet-panel" role="tabpanel" aria-labelledby="tab-${state.tab}"><div class="work-grid planos-fields">${groups[state.tab].map(id=>field(id)).join('')}</div></div><p class="note">Hoy priorizamos D1 y D2. Todas las decisiones siguen disponibles. ${storageOK?'Borrador local guardado.':'Guardado restringido: conserva el registro visible.'} El canvas no se autocalifica.</p><div class="actions">${b('record','Conservar mi canvas')}${t('model','Consultar el modelo completo')}</div>`);
case 12:return scene(n,`<div class="split peer-split"><div><div class="steps"><div class="step"><span class="num">1</span><div><strong>Compartir · 2 min</strong><p>Expliquen aprendizaje y acción esperada de cada canvas.</p></div></div><div class="step"><span class="num">2</span><div><strong>Preguntar · 2 min</strong><p>¿Qué producción permitirá reconocer ese aprendizaje?</p></div></div><div class="step"><span class="num">3</span><div><strong>Ajustar · 2 min</strong><p>Precisen una relación después de escuchar la pregunta.</p></div></div></div><div class="work-grid peer-fields">${field('peer')}${field('revision')}</div></div><aside class="timer-box"><span class="eyebrow">TIEMPO ORIENTATIVO</span><div class="timer" id="timer" role="timer" aria-label="Tiempo restante">${clock()}</div><div class="actions">${b('timer',running?'Pausar':'Iniciar')}${t('timer-reset','Reiniciar')}</div><p class="note">Sin avance automático. El facilitador organiza el intercambio.</p></aside></div>`);
case 13:{const url=window.PLANOS_CONFIG?.canvasExterno,valid=typeof url==='string'&&/^https:\/\//.test(url);return scene(n,`<div class="split"><div>${field('exit')}<div class="actions">${b('record','Conservar mi canvas')}${b('notebook','Seguir editando','',true)}</div><p class="note">Guardar aquí no envía el proyecto ni registra Códigos del Saber.</p></div><aside class="panel"><span class="eyebrow">60 MINUTOS ASINCRÓNICOS</span><h3>Continuar el primer plano</h3><p>Retoma objetivo y conductas. Desarrolla las decisiones restantes con el contexto de tu curso y conserva las preguntas para El Yunque.</p>${valid?`<a class="button secondary" href="${esc(url)}" target="_blank" rel="noopener noreferrer">Abrir canvas externo</a><p class="note">La entrega se realiza por el canal que indique el facilitador. Este HTML no la verifica.</p>`:'<p class="note">Canvas externo pendiente de enlazar. El canvas local completo y su registro son la alternativa disponible.</p>'}</aside></div>`);}
}}
function render(focus=false){document.body.classList.toggle('is-cover',state.page===0);$('stage').innerHTML=page(state.page);$('page-count').textContent=`${state.page+1} / ${N}`;$('previous').disabled=state.page===0;$('next-label').textContent=state.page===N-1?'Mi canvas':'Siguiente';$('route-dots').innerHTML=C.pages.map((p,i)=>`<button class="route-dot ${state.visited.includes(i)?'visited':''} ${i===state.page?'current':''}" data-action="go" data-page="${i}" aria-label="Pantalla ${i+1}: ${p.title}" ${i===state.page?'aria-current="step"':''}></button>`).join('');$('seal-status').innerHTML=C.quizzes.map((q,i)=>`<button class="seal-dot ${state.seals[i]}" data-action="seal" data-quiz="${i}" aria-label="Candado ${q.name}: ${status(state.seals[i])}">${i+1}</button>`).join('');if(focus)$('stage').focus({preventScroll:true});}
function go(n){if(!Number.isInteger(n)||n<0||n>=N)return;if($('modal').open)$('modal').close();state.page=n;if(!state.visited.includes(n))state.visited.push(n);save();history.replaceState(null,'',`#pantalla-${n+1}`);render(true);window.scrollTo({top:0,behavior:'instant'});}
function modal(h,body){if(!$('modal').open)opener=document.activeElement;$('modal-body').innerHTML=`<h2 id="modal-title" tabindex="-1">${h}</h2>${body}`;if(!$('modal').open)$('modal').showModal();$('modal-title').focus({preventScroll:true});}
function close(){const old=opener,d=old?.dataset?{...old.dataset}:null;$('modal').close();render();if(old?.isConnected)old.focus({preventScroll:true});else if(d){[...document.querySelectorAll('[data-action]')].find(x=>Object.entries(d).every(([k,v])=>x.dataset[k]===v))?.focus({preventScroll:true});}}
function toast(msg){clearTimeout(toastTimeout);$('toast').textContent=msg;$('toast').hidden=false;toastTimeout=setTimeout(()=>$('toast').hidden=true,4000);}
function reward(i){modal('La pauta de '+C.quizzes[i].name,`<p>${status(state.seals[i])}. Recurso complementario para conversar.</p><ul class="reward-list">${C.quizzes[i].reward.map(x=>`<li>${x}</li>`).join('')}</ul><p>${C.quizzes[i].options[C.quizzes[i].correct].why}</p><p class="note">Orientaciones didácticas de esta práctica. No es una rúbrica de tesis ni una calificación.</p>`);}
function dimension(id){const d=C.dimensions.find(x=>x.id===id);if(!d)return;if(!state.opened.includes(id))state.opened.push(id);save();modal(d.tag+' · '+d.title,`<p>${d.body}</p><div class="case-panel" style="margin-top:20px"><span class="eyebrow">MODELO FICTICIO · EL CICLO DEL AGUA</span><p>${d.model}</p></div><p class="note">${d.detail}</p><div class="actions">${t('edit','Anotar esta decisión en mi canvas',`data-field-id="${id}"`)}${t('sources','Referencia y alcance')}</div>`);}
function model(){modal('El canvas modelo completo',`<p>Ciencias Naturales · 7.º básico · caso ficticio resuelto para esta clase. No documenta una intervención ni resultados reales.</p><div class="modal-canvas">${C.dimensions.map(d=>`<article><span class="eyebrow">${d.tag}</span><h3>${d.title}</h3><p>${d.model}</p><p class="note">${d.detail}</p></article>`).join('')}</div>`);}
function sources(){modal('Fuentes y alcance',C.sources.map(s=>`<h3>${s.title}</h3><p>${esc(s.apa)}</p><p class="note">${esc(s.use)}</p>${s.url?`<p><a href="${s.url}" target="_blank" rel="noopener noreferrer">Consultar fuente primaria</a></p>`:''}`).join('')+'<p class="note">Canvas, casos, preguntas y secuencias: elaboración didáctica propia. Arte generado específicamente para Ludaria; esquemas y canvas construidos con código.</p>');}
function textRecord(){return ['BUSCADORES DE LA GAMIFICACIÓN PERDIDA','Los Planos del Arquitecto · Sesión 8 · Misión principal · Módulo 3','Fecha: '+new Date().toLocaleDateString('es-CL'),'',...Object.entries(C.fields).flatMap(([id,f])=>[f.label.toUpperCase(),state.fields[id]||'(Sin registro)','']),'PRÁCTICA LOCAL',...C.quizzes.flatMap((q,i)=>[q.name+': '+status(state.seals[i]),'Decisión: '+(q.options[state.choices[i]]?.text||'Sin elegir'),'Pista consultada: '+(state.hints[i]?'Sí':'No')]),'Decisiones consultadas: '+(state.opened.map(id=>C.dimensions.find(d=>d.id===id).tag).join(', ')||'Ninguna'),'Hipótesis de experiencia: '+(['Elegir por dónde explorar','Comparar ideas con un par'][state.interest]||'Sin elegir'),'','Este canvas no se ha enviado desde el HTML. Requiere revisión humana; no acredita Códigos del Saber.','','FUENTES',...C.sources.map(s=>s.apa)].join('\n');}
function record(){modal('Registro de mi canvas',`<p>Conserva el borrador y compártelo por el canal indicado en clase.</p><label class="field" for="export-text">Canvas completo<textarea id="export-text" readonly rows="12">${esc(textRecord())}</textarea></label><div class="actions">${b('copy','Copiar canvas')}${b('download','Descargar TXT','',true)}</div><p class="note">Si el marco restringe copia o descarga, selecciona el texto o abre la misión en otra pestaña.</p>`);}
function notebook(){modal('Mi canvas editable',`<p>Las seis decisiones están siempre disponibles. Hoy priorizamos D1 y D2.</p><div class="work-grid">${Object.keys(C.fields).map(id=>field(id,'book')).join('')}</div><div class="actions">${b('record','Ver registro completo')}</div><p class="note">Borrador local por dispositivo. ${storageOK?'Guardado disponible.':'Guardado restringido: conserva el registro visible.'} Sin envío ni autocalificación.</p>`);}
function guide(){modal('Acompañar Los Planos del Arquitecto',`<p>Principal del módulo 3. Forja · Ondal · Creación. Objetivo: comenzar a aplicar el canvas 6D.</p><ol class="complete-list">${C.pages.map(p=>`<li><strong>${p.title} · ${p.time} min.</strong> ${p.prompt}<br>Producto: ${p.product}</li>`).join('')}</ol><p>90 minutos sincrónicos y 60 asincrónicos según la tesis. El facilitador conduce la explicación y los intercambios. D1 y D2 se inician en clase; las otras decisiones se desarrollan con el contexto personal.</p><p>Revise explicaciones y productos; los sellos son prácticas complementarias. La plantilla y el caso son didácticos y no reproducen instrumentos de evaluación. El canvas externo necesita una URL real, con alternativa local disponible.</p>`);}
document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el||el.disabled)return;const a=el.dataset.action,i=Number(el.dataset.quiz),o=Number(el.dataset.option);switch(a){
case 'begin':go(1);break;case 'go':go(Number(el.dataset.page));break;case 'close':close();break;
case 'map':modal('Los pasos del plano',`<p>Acceso libre a todas las pantallas. ${state.visited.length}/${N} visitadas; recorrido local.</p><div class="modal-grid">${C.pages.map((p,n)=>`<button class="map-item" data-action="go" data-page="${n}"><span>${n+1}</span>${p.title}</button>`).join('')}</div><div class="actions">${t('reset-ask','Reiniciar esta misión')}</div>`);break;
case 'guide':guide();break;case 'sources':sources();break;case 'notebook':notebook();break;case 'record':record();break;case 'model':model();break;case 'dimension':dimension(el.dataset.dim);break;
case 'edit':if(C.fields[el.dataset.fieldId])modal(C.fields[el.dataset.fieldId].label,field(el.dataset.fieldId,'notes')+'<p class="note">Anotación local editable. No hay respuesta automática ni envío.</p>');break;
case 'choice':state.choices[i]=o;state.seals[i]='pending';delete feedback[i];save();render();document.querySelector(`[data-action="choice"][data-quiz="${i}"][data-option="${o}"]`)?.focus({preventScroll:true});break;
case 'check':if(state.choices[i]===null){feedback[i]={kind:'hint',text:'Elige una alternativa antes de revisar. Puedes pedir una pista o consultar la pauta con apoyo.'};render();document.querySelector('.feedback')?.focus({preventScroll:true});break;}if(state.choices[i]===C.quizzes[i].correct){state.seals[i]='solved';save();render();reward(i);}else{feedback[i]={kind:'error',text:C.quizzes[i].options[state.choices[i]].why+' Puedes revisar sin penalización.'};render();document.querySelector('.feedback')?.focus({preventScroll:true});}break;
case 'hint':state.hints[i]=true;save();render();break;
case 'assist':modal('Abrir con acompañamiento',`<p>Conversen la práctica con apoyo. La pauta complementaria puede abrirse y el sello lo distinguirá.</p><div class="actions">${b('assist-confirm','Abrir pauta con apoyo',`data-quiz="${i}"`)}${b('close','Volver a intentar','',true)}</div>`);break;
case 'assist-confirm':state.seals[i]='assisted';save();render();reward(i);break;
case 'seal':if(state.seals[i]!=='pending')reward(i);else go([3,4][i]);break;case 'reward':reward(i);break;
case 'loop':modal(['Explorar','Proponer','Recibir','Revisar'][o],`<p>${['El equipo elige una evidencia: una imagen del fenómeno o una descripción. Debe explicar qué información aporta.','Se comparan dos modelos y se escribe una explicación inicial. El facilitador puede pedir que se señale qué evidencia la sostiene.','Un par pregunta por una relación que necesita aclararse. Feedback posible: “¿Qué parte de esa evidencia permite explicar la condensación?”.','El equipo conserva la primera versión y precisa su explicación. Si la evidencia no alcanza, puede volver a explorar.'][o]}</p><p class="note">Bucle didáctico del caso ficticio. No es una medición automática de aprendizaje.</p>`);break;
case 'interest':state.interest=o;save();render();modal('Una hipótesis para probar',`<p>${o===0?'Elegir la evidencia inicial ofrece una decisión dentro de la tarea. Habría que observar si las elecciones permiten avanzar hacia la explicación.':'Comparar ideas permite contrastar explicaciones con otra persona. Habría que cuidar roles y apoyos para que todas las personas puedan contribuir.'}</p><p class="note">Hipótesis propia para conversar; no es una predicción de efecto ni una respuesta calificada.</p>`);break;
case 'framework':if(o===0)modal('6D · proceso de diseño','<p>Relaciona objetivos, conductas, participantes, bucles, diversión y herramientas. Puede revisarse de manera iterativa.</p><p class="note">Werbach y Hunter (2012). En esta clase se adapta al objetivo pedagógico.</p>');else if(o===1)modal('Octalysis · ocho impulsores',`<p>Chou propone estas lentes para analizar qué invita a participar:</p><ol class="drive-grid">${C.drives.map((d,n)=>`<li>${n+1} · ${d}</li>`).join('')}</ol><p class="note">Traducción propia de la página del creador. No es una clasificación exhaustiva demostrada ni una exigencia de usar los ocho. Se evita presentar metáforas de “cerebro” como neurociencia.</p>`);else modal('Toda et al. · vocabulario de elementos','<p>La propuesta de 2019 reúne 21 elementos y revisa su descripción con expertos. Ayuda a nombrar y comparar decisiones de gamificación educativa.</p><p>En este caso, podemos describir objetivos, progresión, cooperación y narrativa; después justificamos la función que cumplen.</p><p class="note">La validación de la taxonomía no demuestra el efecto de cada elemento sobre aprendizaje. No equivale automáticamente a las seis decisiones del canvas.</p>');break;
case 'tab':state.tab=o;save();render();$('tab-'+o).focus({preventScroll:true});break;
case 'timer':if(state.timer===0)state.timer=360;running=!running;save();render();break;case 'timer-reset':running=false;state.timer=360;save();render();break;
case 'copy':try{if(!navigator.clipboard?.writeText)throw Error();await Promise.race([navigator.clipboard.writeText(textRecord()),new Promise((_,rej)=>setTimeout(()=>rej(Error()),3500))]);toast('Canvas copiado.');}catch(err){$('export-text')?.focus();$('export-text')?.select();toast('Selecciona el canvas y usa Copiar en tu dispositivo.');}break;
case 'download':{const url=URL.createObjectURL(new Blob(['\ufeff'+textRecord()],{type:'text/plain;charset=utf-8'}));const anchor=document.createElement('a');anchor.href=url;anchor.download='Canvas_Los_Planos_del_Arquitecto.txt';document.body.appendChild(anchor);anchor.click();anchor.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);toast('Descarga solicitada; también puedes copiar el registro visible.');break;}
case 'fullscreen':if(document.fullscreenElement)document.exitFullscreen?.();else document.documentElement.requestFullscreen?.().catch(()=>toast('Abre la clase en una pestaña para usar pantalla completa.'));break;
case 'reset-ask':modal('Reiniciar esta misión',`<p>Se borrará únicamente el canvas de Los Planos del Arquitecto en este dispositivo. Conserva el registro primero.</p><div class="actions">${b('reset','Reiniciar')}${b('record','Ver registro antes','',true)}</div>`);break;
case 'reset':state=fresh();running=false;feedback={};save();go(0);break;
}});
document.addEventListener('input',e=>{const id=e.target.dataset.field;if(C.fields[id]){state.fields[id]=e.target.value;save();}});
$('previous').addEventListener('click',()=>go(state.page-1));$('next').addEventListener('click',()=>state.page===N-1?record():go(state.page+1));$('modal').addEventListener('cancel',e=>{e.preventDefault();close();});
document.addEventListener('keydown',e=>{if(e.ctrlKey||e.metaKey||e.altKey||$('modal').open)return;if(e.target.closest('[role="tab"]')&&['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();state.tab=e.key==='Home'?0:e.key==='End'?2:(state.tab+(e.key==='ArrowRight'?1:2))%3;save();render();$('tab-'+state.tab).focus();return;}if(e.target.closest('input,textarea,select,button,a'))return;if(e.key==='ArrowRight'){e.preventDefault();go(state.page+1);}if(e.key==='ArrowLeft'){e.preventDefault();go(state.page-1);}});
window.addEventListener('hashchange',()=>{const m=/^#pantalla-(\d+)$/.exec(location.hash);if(m)go(Number(m[1])-1);});
setInterval(()=>{if(running&&state.page===12){state.timer=Math.max(0,state.timer-1);save();if($('timer'))$('timer').textContent=clock();if(state.timer===0){running=false;render();toast('Terminó el tiempo orientativo; pueden continuar conversando.');}}},1000);
if(!matchMedia('(prefers-reduced-motion: reduce)').matches)$('fireflies').innerHTML=Array.from({length:10},(_,i)=>`<i class="fly" style="left:${(i*37+9)%100}%;top:${(i*19+13)%100}%;animation-delay:-${i}s"></i>`).join('');
const start=/^#pantalla-(\d+)$/.exec(location.hash);if(start&&Number(start[1])>=1&&Number(start[1])<=N)state.page=Number(start[1])-1;if(!state.visited.includes(state.page))state.visited.push(state.page);save();render();
})();
